import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const script = join(import.meta.dirname, '..', 'scripts', 'replace-header.mjs');
const upstream = [
  '/* eslint-disable */',
  '/* tslint:disable */',
  '// @ts-nocheck',
  '/*',
  ' * ---------------------------------------------------------------',
  ' * ## THIS FILE WAS GENERATED VIA SWAGGER-TYPESCRIPT-API        ##',
  ' * ##                                                           ##',
  ' * ## AUTHOR: acacode                                           ##',
  ' * ## SOURCE: https://github.com/acacode/swagger-typescript-api ##',
  ' * ---------------------------------------------------------------',
  ' */',
  ''
].join('\n');

function run(dir: string) {
  return spawnSync('node', [ script, dir ], { encoding: 'utf8' });
}

describe('replace-header script', () => {
  let dir: string;
  beforeEach(() => (dir = mkdtempSync(join(tmpdir(), 'api-header-'))));
  afterEach(() => rmSync(dir, { recursive: true, force: true }));

  it('replaces the known header and keeps the code', () => {
    writeFileSync(join(dir, 'Things.ts'), `${upstream}\nexport const a = 1;\n`);

    const result = run(dir);

    expect(result.status, result.stderr).toBe(0);
    expect(readFileSync(join(dir, 'Things.ts'), 'utf8')).toBe(
      '// Generated by the web-api-client:generate target from apps/server/openapi.json. Do not edit.\n\nexport const a = 1;\n'
    );
  });

  it('fails, and leaves the file alone, when the header is not the known one', () => {
    const changed = `/* a new upstream header */\nexport const a = 1;\n/*\n */\n`;
    writeFileSync(join(dir, 'Things.ts'), changed);

    const result = run(dir);

    expect(result.status).toBe(1);
    expect(result.stderr).toContain('Things.ts');
    expect(readFileSync(join(dir, 'Things.ts'), 'utf8')).toBe(changed);
  });

  it('fails when there is nothing to process', () => {
    expect(run(dir).status).toBe(1);
  });
});
